// src/utils/parseToGraph.js
export function parseToGraph(code) {
  const lines = code
    .split("\n")
    .map(l => l.trim())
    .filter(l => l.length && !l.startsWith("#"));

  let nodes = [];
  let edges = [];
  let stack = [];
  let id = 1;

  function addNode(text, type = "process") {
    const node = { id: id++, text, type };
    nodes.push(node);
    return node;
  }

  let prev = null;

  for (let line of lines) {
    let currentType = "process";
    let node = null;

    // Detect key structures
    if (/^if\s+/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      stack.push(node);
    } else if (/^elif\s+/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      edges.push({ from: stack[stack.length - 1].id, to: node.id, label: "else if" });
      stack.push(node);
    } else if (/^else:/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      edges.push({ from: stack[stack.length - 1].id, to: node.id, label: "else" });
      stack.push(node);
    } else if (/^(for|while)\s+/.test(line)) {
      currentType = "loop";
      node = addNode(line, currentType);
      stack.push(node);
    } else if (/^def\s+/.test(line)) {
      currentType = "function";
      node = addNode(line, currentType);
    } else if (/^return\b/.test(line)) {
      currentType = "return";
      node = addNode(line, currentType);
    } else {
      node = addNode(line);
    }

    if (prev) {
      // connect normal flow
      edges.push({ from: prev.id, to: node.id });
    }

    prev = node;
  }

  return { nodes, edges };
}

